const isCarousel3d = computed(() => props.template?.collection === 'carousel-3d')
const isGrid = computed(() => props.template?.collection === 'grid')
const isOrbit = computed(() => props.template?.collection === 'orbit')
const isGlobe = computed(() => props.template?.collection === 'globe')
const isScale = computed(() => props.template?.collection === 'scale')
const isStories = computed(() => props.template?.collection === 'stories')
const isFlicker = computed(() => props.template?.collection === 'flicker')
const isTest = computed(() => props.template?.collection === 'test')
const isSwipeDepth = computed(() => props.template?.collection === 'swipe-depth')
