        <fieldset v-if="modelValue.gridLayout === 'tube'"><legend>Bend</legend><div class="video-choice-row"><button type="button" :aria-pressed="modelValue.gridTubeBend !== 'inside'" @click="set('gridTubeBend','outside')">Outside</button><button type="button" :aria-pressed="modelValue.gridTubeBend === 'inside'" @click="set('gridTubeBend','inside')">Inside</button></div></fieldset>
