        <div class="video-control-pair"><label><span>Scatter <output>{{ modelValue.gridScatter }}%</output></span><VideoRangeInput min="0" max="100" :value="modelValue.gridScatter" @input="set('gridScatter',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Size variation <output>{{ modelValue.gridScaleVariance }}%</output></span><VideoRangeInput min="0" max="100" :value="modelValue.gridScaleVariance" @input="set('gridScaleVariance',Number(($event.target as HTMLInputElement).value))" /></label></div>
