        <label><span>Plane rotation <output>{{ modelValue.planeRotation }}°</output></span><VideoRangeInput min="-180" max="180" :value="modelValue.planeRotation" @input="set('planeRotation',Number(($event.target as HTMLInputElement).value))" /></label>
        <label><span>Orbit radius <output>{{ modelValue.orbitRadius }}</output></span><VideoRangeInput min="0" max="800" step="10" :value="modelValue.orbitRadius" @input="set('orbitRadius',Number(($event.target as HTMLInputElement).value))" /></label>
        <label><span>Distance <output>{{ modelValue.distance }}</output></span><VideoRangeInput min="200" max="5000" step="10" :value="modelValue.distance" @input="set('distance',Number(($event.target as HTMLInputElement).value))" /></label>
        <label><span>Perspective <output>{{ modelValue.perspective }}</output></span><VideoRangeInput min="50" max="350" step="10" :value="modelValue.perspective" @input="set('perspective',Number(($event.target as HTMLInputElement).value))" /></label>
        <fieldset><legend>Rotation</legend><div class="video-control-pair"><label><span>X <output>{{ modelValue.rotationX }}°</output></span><VideoRangeInput min="-90" max="90" :value="modelValue.rotationX" @input="set('rotationX',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Y <output>{{ modelValue.rotationY }}°</output></span><VideoRangeInput min="-90" max="90" :value="modelValue.rotationY" @input="set('rotationY',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Z <output>{{ modelValue.rotationZ }}°</output></span><VideoRangeInput min="-360" max="360" :value="modelValue.rotationZ" @input="set('rotationZ',Number(($event.target as HTMLInputElement).value))" /></label></div></fieldset>
        <fieldset><legend>Material</legend><div class="video-choice-row"><button type="button" :aria-pressed="modelValue.flipMaterial === 'flat'" @click="set('flipMaterial','flat')">Flat</button><button type="button" :aria-pressed="modelValue.flipMaterial === 'lit'" @click="set('flipMaterial','lit')">Lit</button></div></fieldset>
        <div v-if="modelValue.flipMaterial === 'lit'" class="video-control-pair"><label><span>Light <output>{{ modelValue.flipLightIntensity }}%</output></span><VideoRangeInput min="0" max="200" :value="modelValue.flipLightIntensity" @input="set('flipLightIntensity',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Roughness <output>{{ modelValue.flipRoughness }}%</output></span><VideoRangeInput min="0" max="100" :value="modelValue.flipRoughness" @input="set('flipRoughness',Number(($event.target as HTMLInputElement).value))" /></label></div>
        <label><span>Corner radius <output>{{ modelValue.cornerRadius }} px</output></span><VideoRangeInput min="0" max="200" :value="modelValue.cornerRadius" @input="set('cornerRadius',Number(($event.target as HTMLInputElement).value))" /></label>
        <label><span>Depth fade <output>{{ modelValue.fade }}%</output></span><VideoRangeInput min="0" max="100" :value="modelValue.fade" @input="set('fade',Number(($event.target as HTMLInputElement).value))" /></label>
        <div class="video-control-pair"><label><span>Offset X <output>{{ modelValue.offsetX }}</output></span><VideoRangeInput min="-100" max="100" :value="modelValue.offsetX" @input="set('offsetX',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Offset Y <output>{{ modelValue.offsetY }}</output></span><VideoRangeInput min="-100" max="100" :value="modelValue.offsetY" @input="set('offsetY',Number(($event.target as HTMLInputElement).value))" /></label></div>
        <fieldset><legend>Motion</legend><div class="video-control-pair"><label><span>Cycles <output>{{ modelValue.cycles }}</output></span><VideoRangeInput min="1" max="6" :value="modelValue.cycles" @input="set('cycles',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Cycle angle <output>{{ modelValue.cycleDegrees }}°</output></span><VideoRangeInput min="30" max="360" step="30" :value="modelValue.cycleDegrees" @input="set('cycleDegrees',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Duration <output>{{ modelValue.secondsPerSlide.toFixed(1) }}s</output></span><VideoRangeInput min="1" max="20" step="0.5" :value="modelValue.secondsPerSlide" @input="set('secondsPerSlide',Number(($event.target as HTMLInputElement).value))" /></label></div></fieldset>
        <fieldset><legend>Easing</legend><div class="video-choice-row"><button v-for="option in easings" :key="option.value" type="button" :aria-pressed="modelValue.easing === option.value" @click="set('easing', option.value)">{{ option.label }}</button></div></fieldset>
        <button class="video-reset" type="button" @click="resetCarousel3d">Reset 3D carousel values</button>
      </template>
      <template v-else>
      <fieldset><legend>Scale center</legend><div class="video-choice-row"><button type="button" :aria-pressed="modelValue.scaleCenter" @click="set('scaleCenter',true)">On</button><button type="button" :aria-pressed="!modelValue.scaleCenter" @click="set('scaleCenter',false)">Off</button></div></fieldset>
      <fieldset v-if="modelValue.scaleCenter"><legend>Scale focus</legend><div class="video-choice-row"><button v-for="option in focusOptions" :key="option.value" type="button" :aria-pressed="modelValue.scaleFocus === option.value" @click="set('scaleFocus', option.value)">{{ option.label }}</button></div></fieldset>
      <label v-if="modelValue.scaleCenter"><span>Scale amount <output>{{ modelValue.centerScale.toFixed(2) }}×</output></span><VideoRangeInput min="1" max="2" step="0.05" :value="modelValue.centerScale" @input="set('centerScale',Number(($event.target as HTMLInputElement).value))" /></label>
      <fieldset><legend>Tilt</legend><div class="video-choice-row"><button v-for="option in tiltModes" :key="option.value" type="button" :aria-pressed="modelValue.tiltMode === option.value" @click="set('tiltMode', option.value)">{{ option.label }}</button></div></fieldset>
      <label v-if="modelValue.tiltMode !== 'off'"><span>Amount <output>{{ modelValue.tilt }}%</output></span><VideoRangeInput min="-100" max="100" :value="modelValue.tilt" @input="set('tilt',Number(($event.target as HTMLInputElement).value))" /></label>
      <fieldset><legend>Solo</legend><div class="video-choice-row"><button type="button" :aria-pressed="modelValue.solo" @click="set('solo',true)">On</button><button type="button" :aria-pressed="!modelValue.solo" @click="set('solo',false)">Off</button></div></fieldset>
      <label v-if="!modelValue.solo"><span>Count <output>{{ modelValue.visibleCount }}</output></span><VideoRangeInput min="2" max="20" :value="modelValue.visibleCount" @input="set('visibleCount',Number(($event.target as HTMLInputElement).value))" /></label>
      <label><span>Plane size <output>{{ modelValue.planeSize }} px</output></span><VideoRangeInput min="50" max="3000" step="10" :value="modelValue.planeSize" @input="set('planeSize',Number(($event.target as HTMLInputElement).value))" /></label>
      <label><span>Corner radius <output>{{ modelValue.cornerRadius }} px</output></span><VideoRangeInput min="0" max="500" :value="modelValue.cornerRadius" @input="set('cornerRadius',Number(($event.target as HTMLInputElement).value))" /></label>
      <label><span>Gap <output>{{ modelValue.gap }} px</output></span><VideoRangeInput min="0" max="1000" step="10" :value="modelValue.gap" @input="set('gap',Number(($event.target as HTMLInputElement).value))" /></label>
      <label><span>Edge fade <output>{{ modelValue.fade }}%</output></span><VideoRangeInput min="0" max="100" :value="modelValue.fade" @input="set('fade',Number(($event.target as HTMLInputElement).value))" /></label>
      <div class="video-control-pair"><label><span>Offset X <output>{{ modelValue.offsetX }}</output></span><VideoRangeInput min="-100" max="100" :value="modelValue.offsetX" @input="set('offsetX',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Offset Y <output>{{ modelValue.offsetY }}</output></span><VideoRangeInput min="-100" max="100" :value="modelValue.offsetY" @input="set('offsetY',Number(($event.target as HTMLInputElement).value))" /></label></div>
      <fieldset><legend>Motion</legend><div class="video-control-pair"><label><span>Cycles <output>{{ modelValue.cycles.toFixed(1) }}</output></span><VideoRangeInput min="0.5" max="3" step="0.5" :value="modelValue.cycles" @input="set('cycles',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Duration <output>{{ modelValue.secondsPerSlide.toFixed(1) }}s</output></span><VideoRangeInput min="0.5" max="5" step="0.1" :value="modelValue.secondsPerSlide" @input="set('secondsPerSlide',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Stagger <output>{{ modelValue.staggerFrames }}f</output></span><VideoRangeInput min="0" max="12" :value="modelValue.staggerFrames" @input="set('staggerFrames',Number(($event.target as HTMLInputElement).value))" /></label><label><span>Delay <output>{{ modelValue.delayFrames }}f</output></span><VideoRangeInput min="0" max="60" :value="modelValue.delayFrames" @input="set('delayFrames',Number(($event.target as HTMLInputElement).value))" /></label></div></fieldset>
      <fieldset><legend>Easing</legend><div class="video-choice-row"><button v-for="option in easings" :key="option.value" type="button" :aria-pressed="modelValue.easing === option.value" @click="set('easing', option.value)">{{ option.label }}</button></div></fieldset>
      <button class="video-reset" type="button" @click="resetCarousel">Reset carousel values</button>
      </template>
    </template>
    <fieldset v-if="template?.renderer !== 'webgl' && !isFlicker && !isStories && !isScale"><legend>Transition</legend><div class="video-choice-row"><button v-for="value in ['cut','fade']" :key="value" type="button" :aria-pressed="modelValue.transition === value" @click="set('transition', value as 'cut'|'fade')">{{ optionLabel(value) }}</button></div></fieldset>
    </div>
  </section>
</template>
